435\\u0439\\u0441\\u0438 \\u0434\\u043b\\u044f {title_rus}\",\"blog\":\"\\u0421\\u0442\\u0430\\u0442\\u0442\\u0456 \\u043f\\u0440\\u043e \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"model\":\"\\u0427\\u043e\\u0445\\u043b\\u0438 \\u043d\\u0430 {title_full}\",\"filters\":{\"main\":\"{filter} \\u0434\\u043b\\u044f {category}\",\"theme\":\"\\u0427\\u043e\\u0445\\u043b\\u0438 \\u0437 \\u043c\\u0430\\u043b\\u044e\\u043d\\u043a\\u043e\\u043c {filter} \\u0434\\u043b\\u044f {category}\",\"technic\":\"{category}: {type} {filter}\"}},\"metaTitle\":{\"index\":\"\\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u0441\\u043c\\u0430\\u0440\\u0442\\u0444\\u043e\\u043d\\u0456\\u0432\",\"chekhly\":\"\\u0427\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u0432\",\"blog\":\"\\u0421\\u0442\\u0430\\u0442\\u0442\\u0456 \\u043f\\u0440\\u043e \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u0430\\u0440\\u0438\",\"filter\":\"\\u0427\\u043e\\u0445\\u043b\\u0438 \\u0437 \\u043c\\u0430\\u043b\\u044e\\u043d\\u043a\\u043e\\u043c {filter} \\u0434\\u043b\\u044f {category}\"},\"metaDescription\":{\"index\":\"\\u3010\\u1409 \\u0417\\u0430\\u043c\\u043e\\u0432\\u0438\\u0442\\u0438 \\u0447\\u043e\\u0445\\u043b\\u0438 \\u0434\\u043b\\u044f \\u0442\\u0435\\u043b\\u0435\\u0444\\u043e\\u043d\\u0456\\u0432! \\u0428\\u0438\\u0440\\u043e\\u043a\\u0438\\u0439 \\u0432\\u0438\\u0431\\u0456\\u0440 \\u043c\\u043e\\u0434\\u0435\\u043b\\u0435\\u0439, \\u0432\\u0441\\u0435 \\u0432 \\u043d\\u0430\\u044f\\u0432\\u043d\\u043e\\u0441\\u0442\\u0456! \\u0414\\u043e\\u0441\\u0442\\u0430\\u0432\\u043a\\u0430 \\u043f\\u043e \\u0423\\u043a\\u0440\\u0430\\u0457\\u043d\\u0456: \\u2705XIAOMI, \\u2705IPHONE, \\u2705VIVO, \\u2705SAMSUNG, \\u2705PIXEL, \\u2705TECNO, \\u2705REALME, \\u2705OPPO\",\"blog\":\"\\u0421\\u0442\\u0430\\u0442\\u0442\\u0456. \\u041c\\u0430\\u0433\\u0430\\u0437\\u0438\\u043d \\u0430\\u043a\\u0441\\u0435\\u0441\\u0443\\u04